def get_good_triples(max_sum_sq):
    good_triples = []
    for x in range(-int(max_sum_sq**0.5), int(max_sum_sq**0.5) + 1):
        for y in range(-int(max_sum_sq**0.5), int(max_sum_sq**0.5) + 1):
            for z in range(-int(max_sum_sq**0.5), int(max_sum_sq**0.5) + 1):
                if x == 0 or y == 0 or z == 0:
                    continue

                # Calculate y^x * z^y * x^z
                # We need to be careful with negative bases and fractional powers.
                # y^x is an integer iff (y == 1) or (y == -1) or (x > 0).
                # z^y is an integer iff (z == 1) or (z == -1) or (y > 0).
                # x^z is an integer iff (x == 1) or (x == -1) or (z > 0).

                try:
                    # Check if y^x is an integer
                    if x < 0:
                        if y != 1 and y != -1: continue

                    # Check if z^y is an integer
                    if y < 0:
                        if z != 1 and z != -1: continue

                    # Check if x^z is an integer
                    if z < 0:
                        if x != 1 and x != -1: continue

                    # If all are integers, calculate the product
                    # Using power with float might lose precision, but we're looking for primes.
                    # However, y^x can be very large.
                    # Let's use a more robust way to check if it's a prime.

                    val_y_x = y**x
                    val_z_y = z**y
                    val_x_z = x**z

                    product = val_y_x * val_z_y * val_x_z
                    if is_prime(product):
                        good_triples.append((x, y, z, x**2 + y**2 + z**2))
                except (OverflowError, ZeroDivisionError, ValueError):
                    continue

    # Sort by sum of squares
    good_triples.sort(key=lambda x: x[3])
    return good_triples

