                is_prime_arr[j] = False

    for p in primes:
        max_k = 0
        if p == 2: max_k = 8
        elif p == 3: max_k = 5
        else: max_k = 2

        for a in range(max_k + 1):
            for b in range(max_k + 1):
                for c in range(max_k + 1):
                    if a == 0 and b == 0 and c == 0: continue
                    for sx in [1, -1]:
                        for sy in [1, -1]:
                            for sz in [1, -1]:
                                x = sx * (p**c)
                                y = sy * (p**a)
                                z = sz * (p**b)
                                if x == 0 or y == 0 or z == 0: continue
                                if a*x + b*y + c*z == 1:
                                    is_y_x_int = (x > 0) or (y == 1 or y == -1)
                                    is_z_y_int = (y > 0) or (z == 1 or z == -1)
                                    is_x_z_int = (z > 0) or (x == 1 or x == -1)

                                    if is_y_x_int and is_z_y_int and is_x_z_int:
                                        sign = 1
                                        if x > 0:
                                            if y < 0: sign *= -1
                                        elif x < 0:
                                            if y == -1: sign *= ((-1)**x)
                                        if y > 0:
                                            if z < 0: sign *= -1
                                        elif y < 0:
                                            if z == -1: sign *= ((-1)**y)
                                        if z > 0:
                                            if x < 0: sign *= -1
                                        elif z < 0:
                                            if x == -1: sign *= ((-1)**z)

                                        if sign == 1:
                                            all_good.append((x, y, z, x**2 + y**2 + z**2))

    all_good.sort(key=lambda x: x[3])
    unique_good = []
    seen = set()
    for t in all_good:
        if t not in seen:
            unique_good.append(t)
            seen.add(t)
    unique_good.sort(key=lambda x: x[3])
