        for y in range(-max_val, max_val + 1):
            if y == 0: continue
            for z in range(-max_val, max_val + 1):
                if z == 0: continue

                # Check if y^x z^y x^z is well-defined and a prime
                try:
                    # y^x
                    val_yx = None
                    if x > 0:
                        val_yx = y**x
                    elif x < 0:
                        if y == 1:
                            val_yx = 1
                        elif y == -1:
                            val_yx = 1 if x % 2 == 0 else -1
                        else:
                            continue
                    else: # x == 0, already handled
                        continue

                    # z^y
                    val_zy = None
                    if y > 0:
                        val_zy = z**y
                    elif y < 0:
                        if z == 1:
                            val_zy = 1
                        elif z == -1:
                            val_zy = 1 if y % 2 == 0 else -1
                        else:
                            continue
                    else: # y == 0, already handled
                        continue

                    # x^z
                    val_xz = None
                    if z > 0:
                        val_xz = x**z
                    elif z < 0:
                        if x == 1:
                            val_xz = 1
                        elif x == -1:
                            val_xz = 1 if z % 2 == 0 else -1
                        else:
                            continue
                    else: # z == 0, already handled
                        continue

                    res = val_yx * val_zy * val_xz
                    if is_prime(res):
                        good_triples.append((x, y, z, res, x**2 + y**2 + z**2))
                except OverflowError:
                    continue
                except ZeroDivisionError:
                    continue

    # Sort by sum of squares, then by x, y, z for uniqueness
    good_triples.sort(key=lambda t: (t[4], t[0], t[1], t[2]))
