def get_good_triples(max_val):
    good_triples = []
    for x in range(-max_val, max_val + 1):
        if x == 0: continue
        for y in range(-max_val, max_val + 1):
            if y == 0: continue
            for z in range(-max_val, max_val + 1):
                if z == 0: continue

                try:
                    # Calculate y^x, z^y, x^z as Fractions
                    # For y^x where y < 0 and x is an integer:
                    # if x > 0, y^x is an integer.
                    # if x < 0, y^x = 1 / y^(-x).

                    def power_frac(base, exp):
                        if base == 0:
                            if exp > 0: return Fraction(0)
                            if exp == 0: return Fraction(1)
                            raise ZeroDivisionError
                        # base**exp is always well-defined for integer exp
                        # But for negative exp, we need to be careful with base < 0
                        # For example, (-2)**-2 = 1/(-2)**2 = 1/4.
                        # For example, (-2)**-3 = 1/(-2)**3 = -1/8.
                        # In Python, (-2)**-2 is 0.25, (-2)**-3 is -0.125.
                        # However, if we use Fraction, it's better.
                        # Actually, base**exp for integer exp is fine.
                        # Let's check.
                        return Fraction(base**exp)

                    val_yx = power_frac(y, x)
                    val_zy = power_frac(z, y)
                    val_xz = power_frac(x, z)

                    res = val_yx * val_zy * val_xz
                    if res.denominator == 1 and is_prime(res.numerator):
                        good_triples.append((x, y, z, res.numerator, x**2 + y**2 + z**2))
                except (OverflowError, ZeroDivisionError, ValueError):
                    continue

    good_triples.sort(key=lambda t: (t[4], t[0], t[1], t[2]))
    return good_triples

