def power(base, exp):
    if base == 0:
        if exp == 0: return 1
        return 0
    if base > 0:
        return base**exp
    if base < 0:
        if exp % 2 == 0:
            return (-base)**exp
        else:
            return - ((-base)**exp)
    return None

